for card_ in cards:
 for section in card_['sections']:
  for r in section['rows']:
   for ref in r['refs']:assert ref in source_keys,(r['id'],ref)
data={'schema':1,'source_date':'2026-10-28','cards':cards,'command_matrix':matrix['normalized_rows'],
 'radio_groups':{name:[r['code'] for r in radio[key]] for name,key in [('decimal','decimal'),('three','three_digit'),('situational','situational_including_clearing')]},
 'source_hashes':{p.name:hashlib.sha256(p.read_bytes()).hexdigest() for p in S.iterdir() if p.suffix in('.txt','.json')}}
def lua(v):
 if isinstance(v,dict):return '{'+','.join('['+json.dumps(str(k),ensure_ascii=False)+']='+lua(x) for k,x in v.items())+'}'
 if isinstance(v,list):return '{'+','.join(map(lua,v))+'}'
 if v is None:return 'nil'
 if isinstance(v,bool):return 'true' if v else 'false'
 return json.dumps(v,ensure_ascii=False)
target=ROOT/'moonloader/lib/pa26_important_data.lua'
target.write_text('-- Generated by tools/build-important.py; presentation summaries, original sources stay in the registry.\nreturn '+lua(data)+'\n',encoding='utf-8')
print('Important dashboard: 10 reviewed presentations; references resolved; originals unchanged.')
